import { BooleanColumn, StringColumn } from '@servicenow/sdk/core'
import { Subflow, wfa, ActionDefinition } from '@servicenow/sdk/automation'

export const actionInstance = ActionDefinition({
    $id: Now.ID['pill-action1'],
    name: 'Action Sample',
    annotation: 'the annotation!',
    description: 'description!',
    inputs: {
        inp1: BooleanColumn({
            label: 'input1',
            mandatory: true,
        }),
        inp2: StringColumn({
            label: 'a label',
            mandatory: true,
        }),
        inp3: StringColumn({
            label: 'a label also',
            mandatory: true,
        }),
    },
    outputs: {
        name: BooleanColumn({
            label: 'outputOne',
            mandatory: true,
        }),
        age: StringColumn({
            label: 'output2',
            mandatory: true,
        }),
    },
})

// Create a reusable subflow definition
export const subflowInstance = Subflow(
    {
        $id: Now.ID['reusable-subflow-def'],
        name: 'Reusable Subflow',
        annotation: 'A reusable subflow that processes employee data',
        description: 'This subflow takes employee info and returns processed results',
        inputs: {
            employeeName: StringColumn({
                label: 'Employee Name',
                mandatory: true,
            }),
            isActive: BooleanColumn({
                label: 'Is Active',
                mandatory: true,
            }),
        },
        outputs: {
            processedName: StringColumn({
                label: 'Processed Name',
                mandatory: true,
            }),
            status: StringColumn({
                label: 'Status',
                mandatory: true,
            }),
        },
    },
    (params) => {
        // Subflow uses an action internally
        wfa.action(
            actionInstance,
            {
                $id: Now.ID['subflow-internal-action'],
                uuid: 'a1b2c3d4-e5f6-4a5b-8c9d-0e1f2a3b4c5d',
            },
            {
                inp1: wfa.dataPill(params.inputs.isActive, 'boolean'),
                inp2: wfa.dataPill(params.inputs.employeeName, 'string'),
                inp3: `Processing ${wfa.dataPill(params.inputs.employeeName, 'string')}`,
            }
        )
    }
)

// Main flow that uses both Actions and Subflows with datapills
Subflow(
    {
        $id: Now.ID['e5079955f75944178c2c271549dd76e2'],
        name: 'Datapills Subflow',
        description: 'A flow with datapills referencing actions and subflows!',
        flowPriority: 'LOW',
        annotation: 'the annotation!',
        inputs: {
            isEmployee: BooleanColumn({
                label: 'input1',
                mandatory: true,
            }),
            empName: StringColumn({
                label: 'a label',
                mandatory: true,
            }),
        },
        outputs: {
            something: BooleanColumn({
                label: 'outputOne',
                mandatory: true,
            }),
            somethingElse: StringColumn({
                label: 'output2',
                mandatory: true,
            }),
        },
        flowVariables: {
            flow_variable1: StringColumn({
                label: 'flow_variable1',
                mandatory: true,
            }),
        },
    },
    (params) => {
        // First action instance
        const actionInstance_1 = wfa.action(
            actionInstance,
            {
                $id: Now.ID['f56a03c118f64f7b9c610d4ff472b334'],
                uuid: 'f56a03c1-18f6-4f7b-9c61-0d4ff472b334',
            },
            {
                inp1: wfa.dataPill(params.inputs.isEmployee, 'boolean'),
                inp2: wfa.dataPill(params.inputs.empName, 'string'),
                inp3: `Hello ${wfa.dataPill(params.inputs.empName, 'string')}`,
            }
        )

        // Second action instance
        const actionInstance_2 = wfa.action(
            actionInstance,
            {
                $id: Now.ID['5c88a57b2aab49dea28a91aacbaf6146'],
                uuid: '5c88a57b-2aab-49de-a28a-91aacbaf6146',
            },
            {
                inp1: false,
                inp2: wfa.dataPill(params.flowVariables.flow_variable1, 'string'),
                inp3: `Hello ${wfa.dataPill(params.flowVariables.flow_variable1, 'string')}`,
            }
        )

        // Subflow instance - using the reusable subflow
        const subflow_1 = wfa.subflow(
            subflowInstance,
            {
                $id: Now.ID['subflow-instance-1'],
                uuid: 'd5e6f7a8-b9c0-4d1e-2f3a-4b5c6d7e8f9a',
            },
            {
                employeeName: wfa.dataPill(params.inputs.empName, 'string'),
                isActive: wfa.dataPill(params.inputs.isEmployee, 'boolean'),
            }
        )

        // Third action instance - uses datapills from both actions and subflow
        wfa.action(
            actionInstance,
            {
                $id: Now.ID['b5e4d2eff95c4295ad0c079e3fcd8916'],
                uuid: 'b5e4d2ef-f95c-4295-ad0c-079e3fcd8916',
            },
            {
                inp1: wfa.dataPill(actionInstance_1.name, 'boolean'),
                inp2: `lead test ${wfa.dataPill(actionInstance_1.name, 'boolean')} something ${wfa.dataPill(actionInstance_2.age, 'string')} and ${wfa.dataPill(subflow_1.processedName, 'string')}`,
                inp3: `Subflow status: ${wfa.dataPill(subflow_1.status, 'string')}`,
            }
        )
    }
)
